1: use bevy::prelude::{Vec2, Vec3};
2: 
3: #[derive(Clone, Copy, Debug)]
4: pub(super) struct TreeCardGeometry {
5:     pub(super) center: Vec3,
6:     pub(super) right: Vec3,
7:     pub(super) up: Vec3,
8:     pub(super) width: f32,
9:     pub(super) height: f32,
10:     pub(super) uv_min: Vec2,
11:     pub(super) uv_max: Vec2,
12: }
13: 
14: pub(super) struct TreeCardMeshBuffers<'a> {
15:     pub(super) positions: &'a mut Vec<[f32; 3]>,
16:     pub(super) normals: &'a mut Vec<[f32; 3]>,
17:     pub(super) uvs: &'a mut Vec<[f32; 2]>,
18:     pub(super) indices: &'a mut Vec<u32>,
19: }
20: 
21: pub(super) fn append_tree_card_with_uv(
22:     geometry: TreeCardGeometry,
23:     buffers: TreeCardMeshBuffers<'_>,
24: ) {
25:     let TreeCardGeometry {
26:         center,
27:         right,
28:         up,
29:         width,
30:         height,
31:         uv_min,
32:         uv_max,
33:     } = geometry;
34:     let right = right.normalize() * width * 0.5;
35:     let up = up.normalize() * height * 0.5;
36:     let normal = right.cross(up).normalize_or_zero();
37:     let base = buffers.positions.len() as u32;
38:     buffers.positions.extend_from_slice(&[
39:         (center - right - up).to_array(),
40:         (center + right - up).to_array(),
41:         (center + right + up).to_array(),
42:         (center - right + up).to_array(),
43:     ]);
44:     buffers.normals.extend_from_slice(&[normal.to_array(); 4]);
45:     buffers.uvs.extend_from_slice(&[
46:         [uv_min.x, uv_max.y],
47:         [uv_max.x, uv_max.y],
48:         [uv_max.x, uv_min.y],
49:         [uv_min.x, uv_min.y],
50:     ]);
51:     buffers
52:         .indices
53:         .extend_from_slice(&[base, base + 1, base + 2, base, base + 2, base + 3]);
54: }
